<script>
import { ref, computed, onMounted } from 'vue';
import { useToast } from 'vue-toastification';
import { fetchAllTransactions } from '@/services/pluggy/pluggyService';

export default {
  name: 'RelatorioView',
  setup() {
    const toast = useToast();

    const transactions = ref([]);
    const loading = ref(false);
    const error = ref(null);

    const searchQuery = ref('');
    const selectedType = ref('ALL');
    const dateFrom = ref('');
    const dateTo = ref('');
    const currentPage = ref(1);
    const pageSize = 20;

    const typeFilters = [
      { label: '📊 Todas', value: 'ALL' },
      { label: '↑ Entradas', value: 'CREDIT' },
      { label: '↓ Saídas', value: 'DEBIT' },
    ];

    async function loadTransactions() {
      loading.value = true;
      error.value = null;
      currentPage.value = 1;
      try {
        transactions.value = await fetchAllTransactions();
        if (transactions.value.length === 0) {
          toast.info('Nenhuma transação encontrada no Pluggy.');
        }
      } catch (err) {
        error.value = err.message;
        toast.error('Erro ao buscar transações do Pluggy.');
      } finally {
        loading.value = false;
      }
    }

    onMounted(loadTransactions);

    const filteredTransactions = computed(() => {
      let list = transactions.value;

      if (selectedType.value !== 'ALL') {
        list = list.filter(tx => tx.type === selectedType.value);
      }

      if (searchQuery.value.trim()) {
        const q = searchQuery.value.toLowerCase();
        list = list.filter(tx =>
          (tx.description || '').toLowerCase().includes(q) ||
          (tx.descriptionRaw || '').toLowerCase().includes(q) ||
          (tx.category || '').toLowerCase().includes(q) ||
          (tx.institutionName || '').toLowerCase().includes(q)
        );
      }

      if (dateFrom.value) {
        list = list.filter(tx => tx.date >= dateFrom.value);
      }
      if (dateTo.value) {
        list = list.filter(tx => tx.date <= dateTo.value + 'T23:59:59');
      }

      return list;
    });

    const totalPages = computed(() => Math.max(1, Math.ceil(filteredTransactions.value.length / pageSize)));

    const paginatedTransactions = computed(() => {
      const start = (currentPage.value - 1) * pageSize;
      return filteredTransactions.value.slice(start, start + pageSize);
    });

    const totalCredits = computed(() =>
      filteredTransactions.value
        .filter(tx => tx.type === 'CREDIT')
        .reduce((s, tx) => s + Math.abs(tx.amount), 0)
    );

    const totalDebits = computed(() =>
      filteredTransactions.value
        .filter(tx => tx.type === 'DEBIT')
        .reduce((s, tx) => s + Math.abs(tx.amount), 0)
    );

    const balance = computed(() => totalCredits.value - totalDebits.value);
    const creditCount = computed(() => filteredTransactions.value.filter(tx => tx.type === 'CREDIT').length);
    const debitCount = computed(() => filteredTransactions.value.filter(tx => tx.type === 'DEBIT').length);

    function formattedValue(value) {
      return new Intl.NumberFormat('pt-BR', {
        style: 'currency',
        currency: 'BRL',
      }).format(value);
    }

    function formatDate(dateStr) {
      if (!dateStr) return '—';
      const d = new Date(dateStr);
      return d.toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' });
    }

    return {
      transactions,
      loading,
      error,
      searchQuery,
      selectedType,
      dateFrom,
      dateTo,
      typeFilters,
      filteredTransactions,
      paginatedTransactions,
      currentPage,
      totalPages,
      totalCredits,
      totalDebits,
      balance,
      creditCount,
      debitCount,
      formattedValue,
      formatDate,
      loadTransactions,
    };
  },
};
</script>

